import sys

lo, hi = 1, 100
while lo < hi:
    mid = (lo + hi) // 2
    print(mid, flush=True)
    reply = sys.stdin.readline().strip()
    if reply == "=":
        lo = hi = mid
        break
    if reply == "<":
        hi = mid - 1
    elif reply == ">":
        lo = mid + 1
    else:
        break
print("!", lo, flush=True)

