"""Interactor: 1..100 oralig'ida sonni topish o'yini.

Protokol:
  submission → taxmin (butun son)
  interactor → "<" (sir kichikroq) | ">" (sir kattaroq)
  submission → "! javob"
  interactor → chiqish kodi 0 = AC, 1 = WA
"""
import sys

SECRET = 42
MAX_QUERIES = 20

queries = 0
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    if line.startswith("!"):
        try:
            answer = int(line[1:].strip())
        except ValueError:
            sys.exit(1)
        sys.exit(0 if answer == SECRET else 1)
    queries += 1
    if queries > MAX_QUERIES:
        sys.exit(1)          # juda ko'p so'rov
    try:
        guess = int(line)
    except ValueError:
        sys.exit(1)
    if guess == SECRET:
        print("=", flush=True)
    elif guess > SECRET:
        print("<", flush=True)
    else:
        print(">", flush=True)
sys.exit(1)                   # javobsiz tugadi
